# Part 1 Check: D=3, N=1875. Find minimum k such that N <= 1 + k + k(k-1) + k(k-1)^2
def max_vertices(k):
    return 1 + k + k * (k - 1) + k * (k - 1)**2

k = 1
while max_vertices(k) < 1875:
    k += 1
print(f"Minimum k for N=1875, D=3: {k}")

# Part 2 Check: D'=2, N'=1874. Find minimum Delta' such that N' <= 1 + Delta' + Delta'(Delta'-1)
def max_vertices_d2(delta):
    return 1 + delta + delta * (delta - 1)

delta_prime = 1
while max_vertices_d2(delta_prime) < 1874:
    delta_prime += 1
print(f"Minimum Delta' for N'=1874, D'=2: {delta_prime}")
